        let key = HKDF<SHA256>.deriveKey(
            inputKeyMaterial: SymmetricKey(data: authSharedSecret),
            salt: Self.hkdfSalt,
            info: info,
            outputByteCount: 32
        )
        do {
            let sealedBox = try AES.GCM.SealedBox(
                nonce: AES.GCM.Nonce(data: nonce),
                ciphertext: ciphertext,
                tag: tag
